		sections={
			{id=2118,title="Veil of Shadow",body="Baron Silverlaine curses his current enemy target, reducing magical healing effects done to the target by $23224s1% for $23224d."},
			{id=2119,title="Cursed Veil",body="Baron Silverlaine inflicts $93956s2 Shadow damage and reduces magical healing done by $93956s1% for all enemy targets within $93956A1 yards for $93956d.",difficultyIDs={2,4,5,6}},
			{id=2120,title="Summon Worgen Spirit",body="Baron Silverlaine summons one of four random Worgen Spirits from the past at 70% and 35% health: Odo the Blindwatcher, Razorclaw the Butcher, Rethilgore, or Wolf Master Nandos.$[!2,4\n\nIn Heroic Difficulty, Baron Silverlaine summons a Worgen Spirit at 90%, 60%, and 30% health.$]"},
			{id=2121,title="Odo the Blindwatcher"},
			{id=2122,title="Howling Rage",body="Odo the Blindwatcher increases his Physical damage dealt by $93931s1% and size by $93931s2% for $93931d. This effect stacks up to 5 times."},
			{id=2123,title="Blinding Shadows",body="Odo the Blindwatcher inflicts $93952s1 Shadow damage every second for $93952d"},
			{id=2125,title="Razorclaw the Butcher"},
			{id=2126,title="Spectral Rush",body="Razorclaw leaps at the furthest away enemy target, stunning and inflicting $93928s1 Physical damage every $93930t2 second for $93930d."},
			{id=2127,title="Butcher Drain",body="Whenever Razorclaw inflicts damage with a melee attack, an additional $7485s1 health is drained from the target."},
			{id=2128,title="Rethilgore"},
			{id=2129,title="Soul Drain",body="Rethilgore channels on a random enemy target, immobilizing and draining $93863s1 health every $93863t1 seconds for $93863d. Rethilgore heals for twice the amount of health drained."},
			{id=2130,title="Wolf Master Nandos"},
			{id=2131,title="Claw",body="Nandos rakes his current target, dealing $93861s1% of his normal melee attack in Physical damage."},
			{id=2132,title="Summon Lupine Spirit",body="When Wolf Master Nandos enters combat, he summons three Lupine Spectres to fight at his side for $94199d."},
			{id=2133,title="Lupine Spectre",body="This creature has low health."},
		},
	},
	[98]={
		encounterID=98,
		instanceID=64,
		order=3,
		name="Commander Springvale",
		lore="A loyal soldier, the ghost of Commander Springvale haunts the council room, using unholy strikes to avenge his lord, Baron Silverlaine.",
		dungeonEncounterID=1071,
		uiMapID=310,
		pin={x=0.2804,y=0.5973},
