			{id=4566,title="Opening Statements",body="High Justice Grimstone first selects a random monster for players to fight in the Ring of Law.  Two waves of the same monster type will attack players.  Possible monsters appear in the sections that follow.",difficultyIDs={1,2,3,4}},
			{id=4548,title="Burrowing Thundersnout",difficultyIDs={1,2,3,4}},
			{id=4549,title="Lizard Bolt",body="The Burrowing Thundersnout inflicts Nature damage to a player.",difficultyIDs={1,2,3,4}},
			{id=4550,title="Thunderclap",body="The Burrowing Thundersnout inflicts Nature damage to all players within $15548a1 yards.  Thunderclap reduces the melee attack speed of players by $15548s3% and their movement speed by 55% for $15548d.",difficultyIDs={1,2,3,4}},
			{id=4551,title="Disjunction",body="The Burrowing Thundersnout affects players within $14533a1 yards with Disjunction. Disjunction increases the Fire, Frost, and Arcane damage taken by the player by $14533s1% for $14533d.",difficultyIDs={1,2,3,4}},
			{id=4555,title="Borer Beetle",difficultyIDs={1,2,3,4}},
			{id=4574,title="Pierce Armor",body="Borer Beetle reduces a player's armor by $6016s1% for $6016d.",difficultyIDs={1,2,3,4}},
			{id=4575,title="Putrid Enzyme",body="Borer Beetle increases the Nature and Shadow damage taken by players within $14539a1 yards by $14539s1% for $14539d.",difficultyIDs={1,2,3,4}},
			{id=4556,title="Deep Stinger",difficultyIDs={1,2,3,4}},
