			{id=4577,title="Slowing Poison",body="The Deep Stinger inflicts Slowing Poison to players it damages in melee combat.  Slowing Poison slows a player's melee attack speed by $7992s1% and movement speed by $7992s2% for $7992d.",difficultyIDs={1,2,3,4}},
			{id=4578,title="Barbed Sting",body="The Deep Stinger slows the melee attack speed of all players within $14534a1 yards by $14534s1% for $14534d.",difficultyIDs={1,2,3,4}},
			{id=4557,title="Dark Screecher",difficultyIDs={1,2,3,4}},
