			{id=4558,title="Dredge Worm",difficultyIDs={1,2,3,4}},
			{id=4581,title="Venom Spit",body="The Dredge Worm inflicts Nature damage to a player.  Venom Spit continues to inflict Nature damage to the affected player every $6917t2 seconds for $6917d.",difficultyIDs={1,2,3,4}},
			{id=4582,title="Poison",body="The Dredge Worm inflicts Nature damage to a player every $13298t1 seconds for $13298d.",difficultyIDs={1,2,3,4}},
			{id=4583,title="Dredge Sickness",body="The Dredge Worm reduces all attributes of all players within $14535a1 yards by $14535s1% for $14535d.",difficultyIDs={1,2,3,4}},
			{id=4559,title="Cave Creeper",difficultyIDs={1,2,3,4}},
			{id=4590,title="Poison",body="The Cave Creeper inflicts Poison to any player it damages with a melee attack.  Poison inflicts Nature damage to affected players every $13298t1 seconds for $13298d.",difficultyIDs={1,2,3,4}},
			{id=4591,title="Web",body="The Cave Creeper immobilizes a player for $745d.",difficultyIDs={1,2,3,4}},
			{id=4592,title="Creeper Venom",body="The Cave Creeper inflicts Creeper Venom to all players within $14532a1 yards for $14532d.  Creeper Venom increases Physical damage inflicted to affected players by $14532s1%.",difficultyIDs={1,2,3,4}},
			{id=4567,title="Final Verdict!",body="High Justice Grimstone sends out a single, final monster for players to fight.",difficultyIDs={1,2,3,4}},
			{id=4560,title="Grizzle",difficultyIDs={1,2,3,4}},
