			{id=4561,title="Anub'shiah",difficultyIDs={1,2,3,4}},
			{id=4596,title="Shadow Bolt",body="Anub'shiah inflicts Shadow damage to a player.",difficultyIDs={1,2,3,4}},
			{id=4608,title="Curse of Tongues",body="Anub'shiah forces all players within $15470a1 yards to speak in Demonic, reducing their casting speed by $15470s1% for $15470d.",difficultyIDs={1,2,3,4}},
			{id=4609,title="Enveloping Web",body="Anub'shiah traps a player in webs for $15471d.  Enveloping Web prevents all spell casting, immobilizes the affected player, and slows their melee attack speed by $15471s2%.",difficultyIDs={1,2,3,4}},
			{id=4610,title="Demon Armor",body="Anub'shiah is protect by demonic energies.  Demon Armor increases Anub'shiah's armor, Shadow resistance, and health regeneration.",difficultyIDs={1,2,3,4}},
			{id=4611,title="Banish",body="Anub'shiah banishes a player to the void.  While banished, players are immune to all attacks and spells; but they are unable to take any actions.",difficultyIDs={1,2,3,4}},
