			{id=4562,title="Eviscerator",difficultyIDs={1,2,3,4}},
			{id=4597,title="Anti-Magic Shield",body="Eviscerator surrounds himself with an Anti-Magic Shield that prevents all magic damage for $7121d.",difficultyIDs={1,2,3,4}},
			{id=4598,title="Vicious Rend",body="Eviscerator viciously rends a player, inflicting Physical damage every $14331t1 seconds for $14331d.",difficultyIDs={1,2,3,4}},
			{id=4599,title="Shadow Bolt Volley",body="Eviscerator inflicts Shadow damage to all players within $15245a1 yards.",difficultyIDs={1,2,3,4}},
