	[375]={
		encounterID=375,
		instanceID=228,
		order=7,
		name="Warder Stilgiss",
		lore="After years of dedication to Emperor Thaurissan, the cunning mage Stilgiss was entrusted with protecting his clan's coffers in the Black Vault. The loyal dwarf's close friend Houndmaster Grebmar celebrated the occasion by gifting one of his vicious dogs--Verek--to Stilgiss. The mage has put the beast to good use, keeping it at his side to scare off the vault's would-be thieves.",
		dungeonEncounterID=233,
