			{id=4403,title="Shield Wall",body="Anger'rel increases his defenses for $15062d at 25% remaining health. Anger'rel takes $15062s1% less damage while Shield Wall is active.",difficultyIDs={1,2,3,4}},
			{id=4392,title="Seeth'rel",difficultyIDs={1,2,3,4}},
			{id=4404,title="Frost Armor",body="Seeth'rel armors herself in Frost, increasing her armor and causing melee attacks against her to inflict Chilled.",difficultyIDs={1,2,3,4}},
			{id=4405,title="Chilled",body="Chilled players move $6136s1% slower and attack $6136s2% slower for $6136d.",difficultyIDs={1,2,3,4}},
			{id=4406,title="Blizzard",body="Seeth'rel creates a blizzard that lasts for $8364d.  The blizzard inflicts Frost damage to any player caught within it.",difficultyIDs={1,2,3,4}},
			{id=4407,title="Frostbolt",body="Seeth'rel inflicts Frost damage to a player. Frostbolt slows players it hits by $12675s2% for $12675d.",difficultyIDs={1,2,3,4}},
			{id=4408,title="Frost Ward",body="Seeth'rel protects herself from Frost damage for $15044d or until the Frost Ward has absorbed too much Frost damage.",difficultyIDs={1,2,3,4}},
			{id=4409,title="Frost Nova",body="Seeth'rel inflicts Frost damage to all players within $12674A1 yards.  Players hit by Frost Nova are immobilized for $12674d.",difficultyIDs={1,2,3,4}},
