			{id=4393,title="Dope'rel",difficultyIDs={1,2,3,4}},
			{id=4411,title="Dual Wield",body="Dope'rel wields a dagger in each hand.",difficultyIDs={1,2,3,4}},
			{id=4412,title="Sinister Strike",body="Dope'rel inflicts additional Physical damage to a player with this attack.",difficultyIDs={1,2,3,4}},
			{id=4413,title="Backstab",body="Dope'rel inflicts significant Physical damage to a player when attacking them from behind.",difficultyIDs={1,2,3,4}},
			{id=4414,title="Gouge",body="Dope'rel incapacitates a player with this attack.  Dope'rel can only use this ability on players who are facing him.",difficultyIDs={1,2,3,4}},
			{id=4415,title="Rupture",body="Dope'rel causes a player to bleed for Physical damage every $15583t1 seconds for $15583d.",difficultyIDs={1,2,3,4}},
			{id=4416,title="Evasion",body="Dope'rel gains evasion at 25% remaining health.  Evasion causes Dope'rel to dodge $15087s1% more often for $15087d.",difficultyIDs={1,2,3,4}},
			{id=4394,title="Gloom'rel",difficultyIDs={1,2,3,4}},
