			{id=4429,title="Flurry",body="Hate'rel gains $17687s1% melee haste each time she critically strikes a player.  Flurry can stack up to 3 times and lasts for $17687d.",difficultyIDs={1,2,3,4}},
			{id=4397,title="Doom'rel",difficultyIDs={1,2,3,4}},
			{id=4430,title="Voidwalkers",body="Doom'rel summons three Voidwalkers to aid him in battle.",difficultyIDs={1,2,3,4}},
			{id=4431,title="Banish",body="Doom'rel banishes a player to the void. Banished players cannot move or take actions, and other players and monsters cannot interact with them.  Banish lasts for $8994d.",difficultyIDs={1,2,3,4}},
			{id=6440,title="Curse of Weakness",body="Doom'rel curses a player, reducing their Physical damage done for $12493d.",difficultyIDs={1,2,3,4}},
