	[459]={
		encounterID=459,
		instanceID=237,
		order=3,
		name="Wardens of the Dream",
		lore="Four promising young drakes accompanied Eranikus into the Temple of Atal'Hakkar, eager to prove themselves by serving a great and powerful wyrm. One by one, they were captured and tainted by the Emerald Nightmare, and they now wander the halls of the Sunken Temple, lashing out at all who intrude upon their waking dream.",
		uiMapID=220,
