		sections={
			{id=6575,title="Heroic Leap",body="Armsmaster Harlan leaps into the center of his chamber, inflicting 100% weapon damage as Physical damage to all enemies within $111218A1 yards of the impact point. Armsmaster Harlan immediately begins casting Blades of Light after using this ability."},
			{id=5376,title="Blades of Light",body="Harlan jumps into the center of the room and begins to spin rapidly with his axe. While spinning, Harlan inflicts  $111215m1% weapon damage as Physical damage to all targets within $111394A1 yards. Harlan carries away targets damaged in this way as he continues spinning around the room."},
			{id=5377,title="Dragon's Reach",body="Harlan inflicts $111217m1% of his normal melee damage to all targets in front of him."},
			{id=5378,title="Call for Help",body="Harlan periodically calls two Scarlet Defenders to come to his aid throughout the encounter."},
			{id=5379,title="Scarlet Defender",body="Scarlet Defenders feature heavy armor to protect them from all damage."},
			{id=5380,title="Heavy Armor",body="While a Scarlet Defender wears their Heavy Armor, they take $113959m1% less damage until their armor breaks from taking $113959m2 damage. Defenders also take $111323m1% less damage from area effect damage."},
			{id=5381,title="Unarmored",body="Scarlet Defenders who receive sufficient damage lose their Heavy Armor and take $112920m1% additional damage."},
			{id=6812,title="Berserker Rage",body="When Armsmaster Harlan reaches 50% remaining health, he enters a Berserker Rage.  Every $111221t1 seconds thereafter, Armsmaster Harlan's damage increases by ${$111220m1*2}%."},
		},
	},
	[656]={
		encounterID=656,
		instanceID=311,
		order=2,
		name="Flameweaver Koegler",
		lore="Flameweaver Koegler trains the Scarlet Crusade's more magically minded adepts in the subtle applications of the arcane. Fire is his specialty, and he has used his skills to burn the order's historical tomes, erasing the Crusade's past failures. Apart from books, Koegler's flames have rendered many--undead, students, and trespassers alike--into piles of smoking ash.",
		dungeonEncounterID=1420,
		uiMapID=432,
		pin={x=0.3938,y=0.1563},
		difficultyIDs={1,2,8},
		npcIDs={59150},
