		sections={
			{id=5395,title="Book Burner",body="Flameweaver Kogler tries to light the books ablaze containing the Scarlet Crusade's past. Players may intercept the fiery bolt, which inflicts $113364s2 Fire damage. If Koegler's attack succesfully hits the books, they begin to burn."},
			{id=5396,title="Burning Books",body="The Burning Books inflict $113620s1 Fire damage every $113620t1 sec to enemies within $113620A1 yards for $113616d."},
			{id=5397,title="Greater Dragon's Breath",body="Koegler unleashes a sweeping series of attacks that mimic the deadly fire breath of a Dragon. The Breath inflicts $113653s1 Fire damage, an additional $113653s2 Fire damage every $113653t2 sec., and confuses the target for $113653d."},
			{id=5398,title="Quickened Mind",body="Flameweaver Koegler casts this preparatory spell, making his next three spells cast nearly instantly."},
			{id=5399,title="Fireball Volley",body="Flameweaver Koegler unleashes a barrage of Fireballs, inflicting $113691s1 Fire damage to all enemies within $113691A1 yards."},
			{id=5400,title="Pyroblast",body="Flameweaver Koegler casts a huge Pyroblast at his current target, inflicting $113690s1 Fire damage, then an additional $113690s2 Fire damage every $113690t2 sec for $113690d."},
		},
	},
	[659]={
		encounterID=659,
		instanceID=246,
		order=1,
		name="Instructor Chillheart",
		lore="Course: Introduction to the Dark Arts\n\nInstructor Chillheart journeyed from Northrend to teach aspiring necromancers discipline, harshly punishing those who disappoint her. She commands the icy chill of the north and masterfully uses Scholomance's libraries to deadly effect.",
		dungeonEncounterID=1426,
		uiMapID=476,
		pin={x=0.6529,y=0.6041},
		difficultyIDs={1,2,8,24},
		npcIDs={58633,58664},
		displayIDs={40301},
		loot={
			{itemID=88336,diffs={1},faction=-1},
			{itemID=88337,diffs={1},faction=-1},
			{itemID=88338,diffs={1},faction=-1},
			{itemID=88339,diffs={1},faction=-1},
			{itemID=88335,diffs={1},faction=-1},
			{itemID=143967,diffs={2,24},faction=-1},
			{itemID=144202,diffs={2,24},faction=-1},
			{itemID=144200,diffs={2,24},faction=-1},
			{itemID=144180,diffs={2,24},faction=-1},
			{itemID=144201,diffs={2,24},faction=-1},
		},
		sections={
			{id=5524,title="Stage One: First Lesson"},
			{id=5512,title="Ice Wall",body="Instructor Chillheart summons a wall of ice that slowly sweeps across the room, instantly killing any player it touches."},
			{id=5513,title="Wrack Soul",body="Instructor Chillheart shatters the soul of a player, inflicting $111631s1 Shadow damage every second for $111631d. When Wrack Soul expires, it jumps to another player.",difficultyIDs={2}},
			{id=5551,title="Ice Wrath",body="Instructor Chillheart wreaths a player in ice for $111610d, causing them to inflict $111616s1 Frost damage to all of their allies within $111616A1 yards every second."},
			{id=5514,title="Touch of the Grave",body="Instructor Chillheart's icy touch causes her next 10 melee attacks to inflict an additional $111224s1 Frost damage."},
			{id=5515,title="Frigid Grasp",body="Instructor Chillheart summons ice at a player's location that explodes from the ground, inflicting $114886s1 Frost damage to all nearby players."},
			{id=5516,title="Stage Two: Second Lesson",body="When Instructor Chillheart's physical body dies, the foul magic that animated her escapes back to her phylactery.\n\nFragments of Instructor Chillheart's soul escape the phylactery and animate the tomes of magic scattered throughout the classroom."},
			{id=5518,title="The Anarchist Arcanist"},
			{id=5519,title="Arcane Bomb",body="The Anarchist Arcanist creates an orb of magic that explodes on impact, inflicting $113859s1 Arcane damage to all players within $113859A1 yards."},
			{id=5520,title="Antonidas' Self Help Guide to Standing in Fire"},
			{id=5521,title="Burn",body="Antonidas' Self Help Guide to Standing in Fire inflicts $120027s1 Fire damage to all players within $120027A1 yards of it."},
			{id=5522,title="Wander's Colossal Book of Shadow Puppets"},
			{id=5523,title="Shadow Bolt",body="Wander's Colossal Book of Shadow Puppets hurls bolts of dark magic at random players, inflicting $113809s1 Shadow damage."},
		},
	},
	[660]={
		encounterID=660,
		instanceID=311,
		order=1,
		name="Houndmaster Braun",
		lore="The quickest and surest way to detect the undead is by the scent of rot they carry, and even the most veteran soldier cannot match the olfactory sense of a hound. Houndmaster Braun has bred and trained a savage pack of canines to aid the crusaders in hunting down their foes--living and undead.",
		dungeonEncounterID=1422,
		uiMapID=431,
		pin={x=0.548,y=0.2882},
		difficultyIDs={1,2,8},
		npcIDs={59303},
