	[674]={
		encounterID=674,
		instanceID=316,
		order=3,
		name="High Inquisitor Whitemane",
		lore="At a young age, Sally Whitemane witnessed her family succumb to the horrific plague of undeath as they were traveling through northern Lordaeron. She was then forced to destroy her parents and siblings when they rose as mindless Scourge minions, leaving her racked by guilt and rage. Ever since that day, the fearsome priestess has found fulfillment and pleasure in only one thing: the destruction of undead.",
		dungeonEncounterID=1425,
