	[688]={
		encounterID=688,
		instanceID=316,
		order=1,
		name="Thalnos the Soulrender",
		lore="Thalnos earned repute in the Scarlet Crusade for the brutal torture methods he used to \"purify\" new recruits. Ultimately, the sadistic mage contracted the plague of undeath and arose as a fearsome skeletal being. The vengeful Thalnos now prowls the monastery's graveyard, commanding apparitions and zombified creatures to attack anyone who trespasses on his unholy domain.",
		dungeonEncounterID=1423,
		uiMapID=435,
		pin={x=0.262,y=0.4563},
		difficultyIDs={1,2,8,19},
		npcIDs={59789,244601},
